import { useDeferredValue } from "react";
import type { SearchResultsPage } from "./queries";
import { ItemSection } from "../../components/section/ItemSection";
import { ContinuationItem } from "../../components/continuation/ContinuationItem";
import styles from "./SectionList.module.css";

export interface SectionListProps {
  pages: SearchResultsPage[] | undefined;
  /** Whether the first page renders its first items before the rest. */
  progressive: boolean;
  onLoadMore: () => void;
}

/**
 * The result sections of all loaded pages. New pages render in the
 * background, so the list stays responsive while they are added.
 */
export function SectionList({ pages, progressive, onLoadMore }: SectionListProps) {
  const shownPages = useDeferredValue(pages);
  const continuation = shownPages?.at(-1)?.continuation;
  return (
    <div className={styles.list}>
      <div className={styles.contents}>
        {shownPages?.map((page, p) =>
          page.sections.map((section, i) =>
            section.itemSectionRenderer ? (
              <ItemSection key={`${p}:${section.itemSectionRenderer.trackingParams}:${i}`} data={section.itemSectionRenderer} progressive={progressive && p === 0} />
            ) : null,
          ),
        )}
        {continuation && <ContinuationItem key={shownPages!.length} data={continuation} onVisible={onLoadMore} />}
      </div>
    </div>
  );
}
