import type { Endpoint } from "./endpoints";
import type {
  ChipCloudRenderer,
  ContinuationItemRenderer,
  ItemSectionRenderer,
  SearchAppendResponse,
  SearchHeaderRenderer,
  SearchInitResponse,
  SearchReloadResponse,
  TwoColumnSearchResultsRenderer,
} from "./innertube.gen";
import type { Processed } from "./response";

// The search page model: the header, the result sections, and the token of
// the next page. Responses are turned into pages; the infinite query keeps
// one page per response.

export type SectionItem = { itemSectionRenderer?: ItemSectionRenderer; continuationItemRenderer?: ContinuationItemRenderer };

export interface SearchPage {
  sections: SectionItem[];
  /** The trailing continuation item, if there are more results. */
  continuation: ContinuationItemRenderer | null;
}

export interface SearchHeader {
  header: SearchHeaderRenderer | null;
  estimatedResults: string | null;
}

function splitContinuation(items: SectionItem[]): SearchPage {
  const last = items.at(-1);
  if (last?.continuationItemRenderer) return { sections: items.slice(0, -1), continuation: last.continuationItemRenderer };
  return { sections: items, continuation: null };
}

function fromTwoColumn(results: TwoColumnSearchResultsRenderer | undefined): SearchPage {
  return splitContinuation((results?.primaryContents?.sectionListRenderer?.contents ?? []) as SectionItem[]);
}

export function searchPageFromInit({ response }: Processed<SearchInitResponse>): SearchPage & SearchHeader {
  return {
    ...fromTwoColumn(response.contents?.twoColumnSearchResultsRenderer as TwoColumnSearchResultsRenderer),
    header: (response.header?.searchHeaderRenderer as SearchHeaderRenderer) ?? null,
    estimatedResults: response.estimatedResults ?? null,
  };
}

/** The new results and header of a filter: the reload commands for the search page. */
export function searchPageFromReload({ commands }: Processed<SearchReloadResponse>): SearchPage & Pick<SearchHeader, "header"> {
  let page: SearchPage = { sections: [], continuation: null };
  let header: SearchHeaderRenderer | null = null;
  for (const c of commands) {
    const reload = c.reloadContinuationItemsCommand as
      | { targetId?: string; slot?: string; continuationItems?: Array<{ twoColumnSearchResultsRenderer?: TwoColumnSearchResultsRenderer; searchHeaderRenderer?: SearchHeaderRenderer }> }
      | undefined;
    if (reload?.targetId !== "search-page") continue;
    if (reload.slot === "RELOAD_CONTINUATION_SLOT_HEADER") header = reload.continuationItems?.[0]?.searchHeaderRenderer ?? null;
    else page = fromTwoColumn(reload.continuationItems?.[0]?.twoColumnSearchResultsRenderer);
  }
  return { ...page, header };
}

/** The sections a continuation appends to the results feed. */
export function searchPageFromAppend({ commands }: Processed<SearchAppendResponse>): SearchPage {
  const items: SectionItem[] = [];
  for (const c of commands) {
    const append = c.appendContinuationItemsAction as { targetId?: string; continuationItems?: SectionItem[] } | undefined;
    if (append?.targetId === "search-feed") items.push(...(append.continuationItems ?? []));
  }
  return splitContinuation(items);
}

export function continuationToken(item: ContinuationItemRenderer | null | undefined): string | null {
  return (item?.continuationEndpoint as Endpoint | undefined)?.continuationCommand?.token ?? null;
}

export function chipsOf(header: SearchHeaderRenderer | null): ChipCloudRenderer | null {
  return (header?.chipBar?.chipCloudRenderer as ChipCloudRenderer) ?? null;
}
