import { infiniteQueryOptions } from "@tanstack/react-query";
import { continuation, search } from "../../api/innertube";
import { parseResponse } from "../../model/response";
import { continuationToken, searchPageFromAppend, searchPageFromInit, searchPageFromReload, type SearchHeader, type SearchPage } from "../../model/search";
import type { SearchAppendResponse, SearchInitResponse, SearchReloadResponse } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { networkRequestFinished, networkRequestStarted } from "../../logging/telemetry";

type PageParam = { token: string; clickTrackingParams?: string } | null;

export type SearchResultsPage = SearchPage & Partial<SearchHeader>;

async function fetchPage(query: string, filter: string | null, pageParam: PageParam): Promise<SearchResultsPage> {
  if (pageParam) {
    const text = await continuation("search-append", "/youtubei/v1/search", pageParam.token, pageParam.clickTrackingParams);
    return searchPageFromAppend(parseResponse<SearchAppendResponse>(text));
  }
  if (filter) return searchPageFromReload(parseResponse<SearchReloadResponse>(await continuation("search-reload", "/youtubei/v1/search", filter)));
  return searchPageFromInit(parseResponse<SearchInitResponse>(await search(query)));
}

/**
 * The results of a search: the first page is the search response, or with
 * a filter the filter's reload response; later pages are continuations.
 */
export function searchQueryOptions(query: string, filter: string | null) {
  return infiniteQueryOptions({
    queryKey: ["search", query, filter],
    initialPageParam: null as PageParam,
    queryFn: async ({ pageParam }): Promise<SearchResultsPage> => {
      const request = networkRequestStarted("search", pageParam ? "continuation" : "navigation");
      try {
        const page = await fetchPage(query, filter, pageParam);
        networkRequestFinished(request, true);
        return page;
      } catch (error) {
        networkRequestFinished(request, false);
        throw error;
      }
    },
    getNextPageParam: (last): PageParam | undefined => {
      const token = continuationToken(last.continuation);
      if (!token) return undefined;
      return { token, clickTrackingParams: (last.continuation?.continuationEndpoint as Endpoint | undefined)?.clickTrackingParams };
    },
  });
}
