import { useRef } from "react";
import type { ChipCloudChipRenderer, SearchHeaderRenderer } from "../../model/innertube.gen";
import { chipsOf } from "../../model/search";
import { useImpression } from "../../logging/impressions";
import { ButtonRenderer } from "../../components/button/ButtonRenderer";
import { ChipCloud } from "./ChipCloud";
import styles from "./SearchHeader.module.css";

export interface SearchHeaderProps {
  data: SearchHeaderRenderer;
  /** The token of a chip whose results are loading. */
  pendingChip: string | null;
  onSelectChip: (chip: ChipCloudChipRenderer) => void;
}

/** The bar above the results: filter chips and the filters button. */
export function SearchHeader({ data, pendingChip, onSelectChip }: SearchHeaderProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const chips = chipsOf(data);
  return (
    <div ref={ref} className={styles.header}>
      <div className={styles.chipBar}>{chips && <ChipCloud data={chips} pending={pendingChip} onSelect={onSelectChip} />}</div>
      {data.searchFilterButton?.buttonRenderer && (
        <div className={styles.filterButton}>
          <ButtonRenderer data={data.searchFilterButton.buttonRenderer} />
        </div>
      )}
    </div>
  );
}
