import clsx from "clsx";
import { useRef, useState } from "react";
import type { GridShelfViewModel, ButtonViewModel as ButtonData, ShortsLockupViewModel } from "../../../model/innertube.gen";
import { unwrap } from "../../../model/unwrap";
import { useImpression } from "../../../logging/impressions";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { ShortsLockup } from "../../../components/lockup/ShortsLockup";
import { SectionHeader, type SectionHeaderData } from "../../../components/lockup/SectionHeader";
import { ButtonViewModel } from "../../../components/button/ButtonViewModel";
import styles from "./GridShelf.module.css";

const MIN_ITEM_WIDTH = 180;
const GAP = 8;

function gridLayout(width: number) {
  const perRow = Math.min(6, Math.max(2, Math.floor((width + GAP) / (MIN_ITEM_WIDTH + GAP))));
  return { perRow, itemWidth: width ? (width - GAP * (perRow - 1)) / perRow : MIN_ITEM_WIDTH };
}

/**
 * A grid of Shorts, sized to the container and collapsed to its first rows
 * until the user asks for more.
 */
export function GridShelf({ data }: { data: GridShelfViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const [width, setWidth] = useState(0);
  const [collapsed, setCollapsed] = useState(true);
  const measure = () => setWidth(ref.current?.clientWidth ?? 0);
  useResizeObserver(ref, measure);
  const { perRow, itemWidth } = gridLayout(width);
  const items = data.contents;
  const collapsedRows = Math.ceil((data.minCollapsedItemCount || 1) / perRow);
  const rows = data.enableVerticalExpansion && collapsed ? collapsedRows : Math.ceil(items.length / perRow);
  const showMore = data.enableVerticalExpansion && collapsed && items.length > perRow * collapsedRows;
  const showLess = data.enableVerticalExpansion && !collapsed && rows > collapsedRows;
  const header = unwrap<SectionHeaderData>(data.header, "sectionHeaderViewModel");
  const toggleButton = unwrap<ButtonData>(showMore ? data.showMoreButton : data.showLessButton, "buttonViewModel");
  return (
    <div ref={ref} className={clsx(styles.shelf, (showMore || showLess) && styles.hasBottomButton)} data-renderer="gridShelfViewModel">
      {header && <SectionHeader data={header} />}
      <div>
        {Array.from({ length: rows }, (_, row) => (
          <div key={row} className={styles.row}>
            {items.slice(row * perRow, row * perRow + perRow).map((item, i) => {
              const lockup = unwrap<ShortsLockupViewModel>(item, "shortsLockupViewModel");
              return (
                <div key={lockup?.entityId ?? i} className={styles.item} style={{ width: itemWidth, marginInlineStart: i ? GAP : 0 }}>
                  {lockup && <ShortsLockup data={lockup} />}
                </div>
              );
            })}
          </div>
        ))}
      </div>
      {(showMore || showLess) && toggleButton && (
        <div className={styles.bottomButton}>
          <ButtonViewModel
            data={toggleButton}
            onClick={() => setCollapsed(!collapsed)}
          />
        </div>
      )}
    </div>
  );
}
