import { Activity, useRef, useState, type MouseEvent } from "react";
import type { ExpandableMetadataRenderer } from "../../../model/innertube.gen";
import type { FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { FormattedString } from "../../../components/text/FormattedString";
import { ImgShadow } from "../../../components/image/Image";
import { ButtonRenderer } from "../../../components/button/ButtonRenderer";
import { Renderer } from "../../../renderers/Renderer";
import styles from "./ExpandableMetadata.module.css";

interface Header {
  collapsedTitle?: FormattedText;
  collapsedThumbnail?: { thumbnails?: Array<{ url: string; width?: number }> };
  collapsedLabel?: FormattedText;
  expandedTitle?: FormattedText;
  showLeadingCollapsedLabel?: boolean;
}

function argbToCss(argb: number | undefined): string | undefined {
  if (argb == null) return undefined;
  return `rgba(${(argb >> 16) & 255}, ${(argb >> 8) & 255}, ${argb & 255}, ${(((argb >>> 24) & 255) / 255).toFixed(3)})`;
}

/**
 * A collapsible section under a search result, with a video's chapters or
 * summary. The collapsed content is rendered ahead of time in a hidden
 * Activity, so that expanding it is instant.
 */
export function ExpandableMetadata({ data }: { data: ExpandableMetadataRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const [expanded, setExpanded] = useState(false);
  const header = (data.header ?? {}) as Header;
  const palette = (data.colorData as { lightColorPalette?: Record<string, number> } | undefined)?.lightColorPalette;
  const colors = data.useCustomColors && palette
    ? ({
        "--yt-expandable-section1-color": argbToCss(palette.section1Color),
        "--yt-expandable-section2-color": argbToCss(palette.section2Color),
        "--yt-expandable-primary-title-color": argbToCss(palette.primaryTitleColor),
      } as React.CSSProperties)
    : undefined;
  // The whole header is a click target. Its button is the control for
  // keyboard and screen reader users, and its clicks bubble up to here.
  const onHeaderClick = (e: MouseEvent) => {
    e.stopPropagation();
    setExpanded((x) => !x);
  };
  return (
    <div ref={ref} className={styles.expandable} style={colors}>
      <div className={styles.header} onClick={onHeaderClick}>
        <div className={styles.leftSection}>
          {header.collapsedThumbnail && (
            <div className={styles.thumbnail}>
              <ImgShadow image={header.collapsedThumbnail} width={72} className={styles.thumbnailImage} />
            </div>
          )}
          {header.showLeadingCollapsedLabel && header.collapsedLabel && (
            <div className={styles.prominentLabel}>
              <FormattedString text={header.collapsedLabel} />
            </div>
          )}
          {expanded ? (
            <div className={styles.expandedTitle}>
              <FormattedString text={header.expandedTitle} />
            </div>
          ) : (
            <div className={styles.collapsedTitle}>
              <FormattedString text={header.collapsedTitle} />
            </div>
          )}
        </div>
        <div className={styles.rightSection}>
          {!header.showLeadingCollapsedLabel && header.collapsedLabel && (
            <div className={styles.collapsedLabel}>
              <FormattedString text={header.collapsedLabel} />
            </div>
          )}
          <div className={styles.button}>
            <ButtonRenderer data={(expanded ? data.collapseButton : data.expandButton).buttonRenderer} expanded={expanded} />
          </div>
        </div>
      </div>
      <Activity mode={expanded ? "visible" : "hidden"}>
        <div className={styles.content}>
          <Renderer data={data.expandedContent} />
        </div>
      </Activity>
    </div>
  );
}
