import { useLayoutEffect, useRef, useState } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { ChipCloudChipRenderer, ChipCloudRenderer } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { getText, accessibilityLabel } from "../../model/text";
import { useImpression, logClick } from "../../logging/impressions";
import { useResizeObserver } from "../../hooks/useResizeObserver";
import { ChipShape } from "../../components/chip/ChipShape";
import { ButtonRenderer } from "../../components/button/ButtonRenderer";
import { TouchFeedback } from "../../components/feedback/TouchFeedback";
import styles from "./ChipCloud.module.css";

const messages = defineMessages({
  label: { id: "search.chips.label", defaultMessage: "Search filters" },
});

function Chip({ data, selected, onSelect }: { data: ChipCloudChipRenderer; selected: boolean; onSelect: () => void }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.chip}>
      <ChipShape
        text={getText(data.text)}
        selected={selected}
        label={accessibilityLabel(data as { accessibilityData?: { label?: string } }) || undefined}
        onClick={() => {
          if (selected) return;
          logClick(data);
          onSelect();
        }}
      />
      <TouchFeedback className={styles.feedback} />
    </div>
  );
}

function overflowsRight(scroller: HTMLElement): boolean {
  return scroller.scrollWidth - scroller.offsetWidth - scroller.scrollLeft > 1;
}

/** The token that asks the server for a chip's filtered results. */
export function chipToken(chip: ChipCloudChipRenderer): string {
  return (chip.navigationEndpoint as Endpoint | undefined)?.continuationCommand?.token ?? getText(chip.text);
}

export interface ChipCloudProps {
  data: ChipCloudRenderer;
  /** The token of a chip whose results are loading; it shows as selected. */
  pending: string | null;
  onSelect: (chip: ChipCloudChipRenderer) => void;
}

/** A scrolling bar of filter chips, with arrows when it overflows. */
export function ChipCloud({ data, pending, onSelect }: ChipCloudProps) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  const scrollerRef = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const chips = data.chips.flatMap((c) => (c.chipCloudChipRenderer ? [c.chipCloudChipRenderer as ChipCloudChipRenderer] : []));
  const pendingIndex = pending === null ? -1 : chips.findIndex((c) => chipToken(c) === pending);
  const selected = pendingIndex >= 0 ? pendingIndex : Math.max(0, chips.findIndex((c) => c.isSelected));
  const [leftArrow, setLeftArrow] = useState(false);
  const [rightArrow, setRightArrow] = useState(false);
  const updateArrows = () => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    setLeftArrow(scroller.scrollLeft > 0);
    setRightArrow(overflowsRight(scroller));
  };
  useResizeObserver(scrollerRef, updateArrows);
  // New chips can overflow the bar without changing its size.
  useLayoutEffect(() => {
    const scroller = scrollerRef.current;
    if (scroller) setRightArrow(overflowsRight(scroller));
  }, [data.chips]);
  const scroll = (direction: 1 | -1) => {
    const scroller = scrollerRef.current;
    if (scroller) scroller.scrollLeft += (direction * scroller.offsetWidth) / 2;
  };
  return (
    <div ref={ref} className={styles.cloud}>
      {leftArrow && (
        <div className={styles.leftArrow}>
          <ButtonRenderer data={data.previousButton.buttonRenderer} onClick={() => scroll(-1)} />
        </div>
      )}
      <div ref={scrollerRef} className={styles.scroller} onScroll={updateArrows}>
        <div className={styles.chips} role="group" aria-label={intl.formatMessage(messages.label)}>
          {chips.map((chip, i) => (
            <Chip
              key={chip.trackingParams}
              data={chip}
              selected={i === selected}
              onSelect={() => onSelect(chip)}
            />
          ))}
        </div>
      </div>
      {rightArrow && (
        <div className={styles.rightArrow}>
          <ButtonRenderer data={data.nextButton.buttonRenderer} onClick={() => scroll(1)} />
        </div>
      )}
    </div>
  );
}
