import { useId, useRef, type MouseEvent } from "react";
import { useNavigate } from "react-router";
import type { VideoRenderer as VideoRendererData } from "../../../model/innertube.gen";
import { endpointHref, type Endpoint } from "../../../model/endpoints";
import { getText, accessibilityLabel, type FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { flags } from "../../../flags";
import { Thumbnail, type ThumbnailOverlay } from "../../../components/thumbnail/Thumbnail";
import { EndpointLink } from "../../../components/text/EndpointLink";
import { FormattedString } from "../../../components/text/FormattedString";
import { ImgShadow } from "../../../components/image/Image";
import { ChannelName } from "../../../components/channel/ChannelName";
import { BadgeList } from "../../../components/badge/MetadataBadge";
import { Menu } from "../../../components/menu/Menu";
import { Tooltip } from "../../../components/feedback/Tooltip";
import { TouchFeedback } from "../../../components/feedback/TouchFeedback";
import { Icon } from "../../../components/icon/Icon";
import { VideoMetaBlock } from "../../../components/lockup/VideoMetaBlock";
import { ExpandableMetadata } from "./ExpandableMetadata";
import styles from "./VideoRenderer.module.css";

interface MetadataSnippet {
  snippetText?: FormattedText;
  snippetHoverText?: FormattedText;
  snippetTimestamp?: FormattedText;
  timestampEndpoint?: Endpoint;
  maxOneLine?: boolean;
}

function Snippet({ data }: { data: MetadataSnippet }) {
  const tooltipId = useId();
  const hoverText = getText(data.snippetHoverText);
  return (
    <div className={data.maxOneLine ? styles.snippetOneLine : styles.snippet}>
      {data.snippetTimestamp ? (
        <EndpointLink
          endpoint={data.timestampEndpoint}
          className={styles.snippetTimestamp}
          aria-label={accessibilityLabel(data.snippetTimestamp)}
          aria-describedby={hoverText ? tooltipId : undefined}
        >
          <span className={styles.time}>{getText(data.snippetTimestamp)}</span>
          <FormattedString text={data.snippetText} />
        </EndpointLink>
      ) : (
        <FormattedString text={data.snippetText} className={styles.snippetText} />
      )}
      <Tooltip text={hoverText} id={data.snippetTimestamp ? tooltipId : undefined} />
    </div>
  );
}

/** A video in the search results: thumbnail, title, metadata, channel and chapters. */
export function VideoRenderer({ data }: { data: VideoRendererData }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const navigate = useNavigate();
  const endpoint = data.navigationEndpoint as Endpoint;
  const channelThumbnail = data.channelThumbnailSupportedRenderers?.channelThumbnailWithLinkRenderer;
  const biggerThumbs = flags.bool("enable_desktop_search_bigger_thumbs");
  const title = getText(data.title);
  const onTextClick = (e: MouseEvent<HTMLDivElement>) => {
    if ((e.target as Element).closest("a, button")) return;
    const href = endpointHref(endpoint);
    if (href) navigate(href, { state: { endpoint } });
  };
  return (
    <div ref={ref} className={styles.video} data-renderer="videoRenderer" data-bigger-thumbs={biggerThumbs || undefined}>
      <div className={styles.dismissible}>
        <Thumbnail
          className={styles.thumbnail}
          thumbnail={data.thumbnail}
          endpoint={endpoint}
          overlays={data.thumbnailOverlays as ThumbnailOverlay[]}
          width={biggerThumbs ? 500 : 360}
        />
        <div className={styles.textWrapper} onClick={onTextClick}>
          <div className={styles.meta}>
            <div className={styles.titleWrapper}>
              <h3 className={styles.title}>
                <EndpointLink
                  endpoint={endpoint}
                  className={styles.videoTitle}
                  data-title-link=""
                  aria-label={accessibilityLabel(data.title) || undefined}
                  title={title}
                >
                  {data.inlinePlaybackEndpoint && data.badges?.length === 0 && <Icon icon="PLAY_ARROW" className={styles.inlineIcon} />}
                  <FormattedString text={data.title} noLinks />
                </EndpointLink>
              </h3>
              {data.menu?.menuRenderer && (
                <div className={styles.menu}>
                  <Menu data={data.menu.menuRenderer} />
                </div>
              )}
            </div>
            <VideoMetaBlock data={data} />
          </div>
          <div className={styles.channelInfo}>
            {channelThumbnail && (
              <EndpointLink
                endpoint={channelThumbnail.navigationEndpoint as Endpoint}
                className={styles.channelThumbnail}
                aria-label={accessibilityLabel(channelThumbnail.accessibility as { accessibilityData?: { label?: string } })}
              >
                <ImgShadow image={channelThumbnail.thumbnail} width={24} className={styles.avatar} />
              </EndpointLink>
            )}
            <ChannelName name={data.longBylineText} badges={data.ownerBadges} wrapText className={styles.channelName} />
          </div>
          {data.detailedMetadataSnippets?.map((snippet, i) => (
            <Snippet key={i} data={snippet as MetadataSnippet} />
          ))}
          <BadgeList badges={data.badges} className={styles.badges} />
          {data.expandableMetadata?.expandableMetadataRenderer && (
            <div className={styles.expandableMetadata}>
              <ExpandableMetadata data={data.expandableMetadata.expandableMetadataRenderer} />
            </div>
          )}
        </div>
      </div>
      <TouchFeedback className={styles.feedback} />
    </div>
  );
}
