import type { AttributedText } from "../../model/text";
import { Icon } from "../icon/Icon";
import { AttributedString } from "../text/AttributedString";
import styles from "./SectionHeader.module.css";

export interface SectionHeaderData {
  headline?: AttributedText;
  leadingAccessory?: { image?: { sources?: Array<{ clientResource?: { imageName?: string } }> } };
}

/** A shelf's header: an optional leading icon and the title. */
export function SectionHeader({ data }: { data: SectionHeaderData }) {
  const icon = data.leadingAccessory?.image?.sources?.[0]?.clientResource?.imageName;
  return (
    <div className={styles.header}>
      <div className={styles.layout}>
        <div className={styles.row}>
          {icon && (
            <div className={styles.leadingImage}>
              <Icon icon={icon} label={icon} />
            </div>
          )}
          <div className={styles.labels}>
            <div className={styles.titleRow}>
              <div className={styles.titleWrapper}>
                <h2 className={styles.title}>
                  <AttributedString text={data.headline} inheritLinkColor />
                </h2>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
