import { keepPreviousData, useInfiniteQuery } from "@tanstack/react-query";
import { useRef, useState } from "react";
import { useMatch, useSearchParams } from "react-router";
import { flags } from "../../flags";
import { emitStepEvent } from "../../workload/events";
import { useNavigationFinished, useNavigationTelemetry } from "../../hooks/useNavigationTelemetry";
import { useOnSettled } from "../../hooks/useOnSettled";
import { searchQueryOptions } from "./queries";
import { SearchHeader } from "./SearchHeader";
import { SectionList } from "./SectionList";
import { chipToken } from "./ChipCloud";
import "./renderers";
import styles from "./SearchPage.module.css";

/**
 * The results page, one instance per query. While another page is shown,
 * this one stays mounted but hidden (PageStack) and keeps its last query.
 */
export default function SearchPage() {
  const [params] = useSearchParams();
  const active = useMatch("/results") !== null;
  const urlQuery = params.get("search_query") ?? "";
  const [query, setQuery] = useState(urlQuery);
  if (active && urlQuery !== query) setQuery(urlQuery);
  return <SearchResults key={query} query={query} />;
}

function SearchResults({ query }: { query: string }) {
  useNavigationTelemetry("results", "search");
  const [filter, setFilter] = useState<string | null>(null);
  const results = useInfiniteQuery({ ...searchQueryOptions(query, filter), placeholderData: keepPreviousData });
  const header = results.data?.pages[0]?.header ?? null;
  useNavigationFinished(results.data !== undefined);

  const lastShown = useRef<{ filter: string | null; pages: number } | null>(null);
  useOnSettled(results.isPlaceholderData ? undefined : results.data, (data) => {
    const previous = lastShown.current;
    lastShown.current = { filter, pages: data.pages.length };
    if (!previous) emitStepEvent("navigate-finish");
    else if (previous.filter !== filter) emitStepEvent("reload-applied", "search-page");
    else if (data.pages.length > previous.pages) emitStepEvent("continuation-applied", "search-feed");
  });

  const loadMore = () => {
    if (results.hasNextPage && !results.isFetchingNextPage && !results.isPlaceholderData) void results.fetchNextPage();
  };
  return (
    <div className={styles.page} data-page="search">
      <div className={styles.container}>
        <div className={styles.header}>{header && (
            <SearchHeader data={header} pendingChip={results.isPlaceholderData ? filter : null} onSelectChip={(chip) => setFilter(chipToken(chip))} />
          )}</div>
        <div className={styles.results} data-bigger-thumbs={flags.bool("enable_desktop_search_bigger_thumbs") || undefined}>
          <div className={styles.primary} aria-busy={results.isPlaceholderData}>
            <SectionList pages={results.data?.pages} progressive={filter === null} onLoadMore={loadMore} />
          </div>
        </div>
      </div>
    </div>
  );
}
